erty claim valuation"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://nebraskainsuranceappraiser.com/#website","url":"https://nebraskainsuranceappraiser.com/","name":"Nebraska Insurance Appraiser","publisher":{"@id":"https://nebraskainsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#webpage","url":"https://nebraskainsuranceappraiser.com/appraisal-word-list/","name":"Insurance Claim Word List | Appraisal Terms Defined","description":"A searchable word list of insurance claim and appraisal terms, from actual cash value and holdback to umpire and wind/hail deductible.","inLanguage":"en-US","isPartOf":{"@id":"https://nebraskainsuranceappraiser.com/#website"},"about":{"@id":"https://nebraskainsuranceappraiser.com/#business"},"publisher":{"@id":"https://nebraskainsuranceappraiser.com/#business"},"dateModified":"2026-11-14","breadcrumb":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#breadcrumb"},"primaryImageOfPage":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#primaryimage"},"mainEntity":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"ImageObject","@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#primaryimage","url":"https://nebraskainsuranceappraiser.com/assets/img/photos/calculator-laptop.webp","contentUrl":"https://nebraskainsuranceappraiser.com/assets/img/photos/calculator-laptop.webp","width":960,"height":640,"caption":"Calculator resting on printed charts next to a laptop"},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://nebraskainsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Appraisal word list","item":"https://nebraskainsuranceappraiser.com/appraisal-word-list/"}],"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#breadcrumb"},{"@type":"DefinedTermSet","name":"Insurance claim and appraisal word list","hasDefinedTerm":[{"@type":"DefinedTerm","name":"Actual cash value (ACV)","description":"Replacement cost minus depreciation. Often the first payment on a replacement cost policy.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Additional living expense (ALE)","description":"Extra costs of living elsewhere while a home is uninhabitable after a covered loss.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Amount of loss","description":"The dollar value of a covered loss. The only question an appraisal panel decides.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Appraisal clause","description":"The policy condition that lets either side demand appraisal when they disagree on the amount of loss.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Appraisal award","description":"The written decision signed by two of the three panel members that sets the amount of loss.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Appraiser","description":"The person each side selects to value the loss. Policies often require that they be competent and impartial.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Bad faith","description":"A legal claim that an insurer unreasonably handled or denied a claim. Not decided in appraisal.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Coinsurance","description":"A commercial policy clause that can reduce payment if a building is insured for less than a set share of its value.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Collapse","description":"A named coverage, often limited to specific causes such as the weight of ice or snow.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Cosmetic damage exclusion","description":"Policy language, common on metal roofs, that excludes dents that do not affect function.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Coverage A","description":"Dwelling coverage on a homeowners policy. Percentage deductibles are often based on this limit.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Coverage B","description":"Other structures coverage, such as detached garages, sheds and fences.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Declarations page","description":"The summary page of a policy listing coverages, limits, deductibles and endorsements.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Depreciation","description":"The reduction in value due to age, wear and obsolescence.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Derecho","description":"A widespread, long-lived windstorm with straight-line winds, often causing damage across hundreds of miles.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Drip edge","description":"Metal flashing along roof edges. Often required by code when a roof is replaced.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Endorsement","description":"A form that adds, removes or changes coverage in a policy.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Functional damage","description":"Damage that affects how a material performs, such as a fractured shingle mat.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Holdback","description":"Depreciation withheld until repairs are complete. Also called recoverable depreciation.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Ice and water shield","description":"A self-adhering underlayment used at eaves and valleys to resist ice dam leaks.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Ice dam","description":"A ridge of ice at the roof edge that traps meltwater, which can back up under shingles.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Line item","description":"A single entry in an estimate for a specific task, quantity and price.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Matching","description":"Whether repaired areas can reasonably match undamaged areas in color and appearance.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Mitigation","description":"Steps taken to prevent further damage after a loss, such as tarping or drying.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Nebraska Department of Insurance","description":"The state agency that regulates insurers and accepts consumer complaints.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Ordinance or law coverage","description":"Coverage for added costs to meet current building codes during repair.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Overhead and profit (O&P)","description":"A general contractor’s markup, often 10% and 10%, when multiple trades are involved.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Percentage deductible","description":"A deductible equal to a percentage of a coverage limit rather than a flat dollar amount.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Pitch","description":"Roof slope, expressed as inches of rise per 12 inches of run, such as 6/12.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Proof of loss","description":"A sworn statement of the amount claimed, often required within a set time after the insurer requests it.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Recoverable depreciation","description":"Depreciation that can be paid once repairs are completed under a replacement cost policy.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Replacement cost value (RCV)","description":"The cost to repair or replace with materials of like kind and quality, without depreciation.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Scope of loss","description":"The list of damaged items and repairs included in an estimate.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Soft metals","description":"Vents, flashing, gutters and similar components that show hail dents clearly.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Square","description":"100 square feet of roof surface.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Steep charge","description":"Extra labor added for working on roofs above a certain pitch.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Supplement","description":"A request to add missed or underpriced items to an estimate.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Suit limitation","description":"The policy period within which a lawsuit against the insurer must be filed.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Umpire","description":"The neutral third panel member who resolves items the two appraisers cannot agree on.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Wind/hail deductible","description":"A separate deductible for windstorm and hail losses, often a percentage of Coverage A.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}},{"@type":"DefinedTerm","name":"Xactimate","description":"Estimating software widely used by insurers and contractors to price property repairs.","inDefinedTermSet":{"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset"}}],"@id":"https://nebraskainsuranceappraiser.com/appraisal-word-list/#definedtermset","publisher":{"@id":"https://nebraskainsuranceappraiser.com/#business"}}]}</script>
</head>
